// Parts is what this application's own wiring built, as far as the process
// around it has to care: the routes to serve, and the notification engine and
// the sync proxy — the things whose lifetime is longer than a request's.
//
// Every field beside the handler is something rig starts, drains or closes on
// the other side of the one call that returns this, and each used to be a line
// in a main function — with no compiler, no test and usually no symptom
// until a deploy under load. Naming them here is what makes them slots to fill
// rather than calls to remember, and what makes turning a block on in rig.yaml
// show up as a field in the one function that has to know about it.
//
// Handler is required. The rest may be nil, because rig cannot tell a project
// that meant it from one that forgot: an engine is latency and the
// `dispatch-notifications` task is the guarantee behind it, and every project
// with an inbox gets a shape over rig_notification_recipient whether or not it
// runs a sync service at all. What a nil one gets instead is a line at startup
// naming what is not running and what that costs.
type Parts struct {
	// Handler is every route this server answers: the generated API, and anything
	// else this application mounts beside it.
	//
	// An http.Handler rather than the mux it probably is, so that the
	// cross-cutting wrappers go here — a panic recovery, a compressor, a
	// middleware of your own. rig answers the two probes outside whatever this is,
	// so a readiness check every second is not a request through all of it.
	Handler http.Handler

	// Engine turns a committed notification into inbox lines, and is
	// [NewNotificationEngine]'s return value.
	//
	// Started and shut down by rig, because both ends of it are numbers out of
	// rig.yaml. What it is built from is not: the audience for a notification is a
	// method on a service, so the registry it resolves through is filled where
	// this application builds its services.
	Engine *notify.Engine

	// Proxy is the sync service this server's shape routes forward through — the
	// same *electric.Proxy given to Handlers.Shapes, named again here.
	//
	// Twice because the two uses are different questions. Register mounts the
	// routes with it and cannot fail; this is the one that asks the sync service
	// whether it is there, while the server is still starting and while refusing
	// to start is still an option. [CheckSyncService] is what happens to the
	// answer.
	//
	// Nil is allowed, and is what a project that generated its shapes and has not
	// written a front end for them yet has. It is said out loud rather than
	// refused, because rig cannot tell that project from one that meant to wire a
	// proxy and did not.
	Proxy *electric.Proxy
}

// Build is this application's own wiring: everything the server is made of,
// from a pool that is already open.
//
// It runs inside the startup budget, before anything is listening, and
// anything it builds with a shutdown of its own is registered on the app it is
// given — beside the line that built it, the way rig registers its own
// below.
//
// A function rather than a value, because a task builds the same object graph
// the server does and has no App to build it from. Keeping the application's
// own constructor taking a pool, and adapting it here, is what lets
// `dispatch-notifications` ask a service who should be told:
//
//	api.Main(cfg, func(ctx context.Context, app *serve.App) (api.Parts, error) {
//		return myapp.New(ctx, app.Pool, app.Logger)
//	})
type Build func(ctx context.Context, app *serve.App) (Parts, error)

// Mount is a [Build] as a serve.Mount, with everything rig starts before it
// and everything rig shuts down registered after it.
//
// [Main] is this and a serve.Config; this is for a caller keeping the process
// — serve.Run in a test, a binary that is more than a server. The order is
// the same either way, which is the reason to reach for this rather than write
// the sequence out:
//
//	serve.Run(ctx, cfg, api.Mount(build))
//
// app.Logger is labelled with the request before build is called, so
// everything built out of it — the services, their repositories, the
// authentication configuration — writes lines that say which request they
// belong to. See [github.com/simonjanss/rig/runtime/apibase.RequestLogger].
//
// What comes back is registered in the order it has to be, and anything left
// nil is said out loud on the way past — see [Parts].
func Mount(build Build) serve.Mount {
	return func(ctx context.Context, app *serve.App) (http.Handler, error) {
		app.Logger = apibase.RequestLogger(app.Logger)

		parts, err := build(ctx, app)
		if err != nil {
			return nil, err
		}

		if parts.Handler == nil {
			return nil, errors.New("api: Parts.Handler is nil: there is nothing to serve")
		}

		if parts.Engine != nil {
			StartNotificationEngine(app, parts.Engine)
		} else {
			// Said rather than left to be discovered. Leaving it out is allowed — rig
			// cannot tell a project that meant it from one that forgot — so what it can
			// do is say so once, while it is still cheap to fix.
			app.Logger.InfoContext(ctx, "no notification engine in this server", "cost", "an inbox line waits for the dispatch-notifications task rather than arriving milliseconds after the commit")
		}

		if parts.Proxy != nil {
			if err := CheckSyncService(ctx, app, parts.Proxy); err != nil {
				return nil, err
			}
		} else {
			// Said rather than left to be discovered. Leaving it out is allowed — rig
			// cannot tell a project that meant it from one that forgot — so what it can
			// do is say so once, while it is still cheap to fix.
			app.Logger.InfoContext(ctx, "no sync service in this server", "cost", "no shape route is mounted and nothing on this server live-syncs")
		}

		return parts.Handler, nil
	}
}

